CREATE TABLE roles(id VARCHAR(32) PRIMARY KEY, name VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE permissions(permission_key VARCHAR(100) PRIMARY KEY, name VARCHAR(200) NOT NULL) ENGINE=InnoDB;
CREATE TABLE role_permissions(role_id VARCHAR(32) NOT NULL, permission_key VARCHAR(100) NOT NULL, PRIMARY KEY(role_id,permission_key), FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(32) NOT NULL,active TINYINT NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id VARCHAR(191) NULL,before_json JSON NULL,after_json JSON NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),KEY(entity_type,entity_id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE command_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,idempotency_key VARCHAR(191) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,command VARCHAR(100) NOT NULL,user_id BIGINT UNSIGNED NULL,status VARCHAR(32) NOT NULL,result_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT INTO roles(id,name) VALUES ('admin','Администратор'),('director','Директор'),('manager','Менеджер'),('lawyer','Юрист'),('accountant','Бухгалтер'),('viewer','Наблюдатель');
INSERT INTO role_permissions(role_id,permission_key) VALUES ('admin','*'),('director','*'),('manager','rental.read'),('manager','rental.write'),('lawyer','rental.read'),('lawyer','rental.approve.legal'),('accountant','rental.read'),('accountant','finance.write'),('viewer','rental.read');
